# Test the full approach with both date.today and datetime.now mocking
import sys
import datetime as real_dt
from unittest import mock

class FakeDate(real_dt.date):
    @classmethod
    def today(cls):
        return real_dt.date(2023, 10, 15)

def make_fake_datetime():
    """Create a fake datetime class that handles now() with different timezones."""
    class FakeDatetime(real_dt.datetime):
        @classmethod
        def now(cls, tz=None):
            if tz is None:
                # Default: system UTC date is Oct 15
                return real_dt.datetime(2023, 10, 15, 13, 0, tzinfo=real_dt.timezone.utc)
            else:
                # In the given timezone, it is Oct 16
                return real_dt.datetime(2023, 10, 16, 0, 0, tzinfo=tz)
    return FakeDatetime

FakeDatetime = make_fake_datetime()

fake_datetime_module = mock.MagicMock(spec=real_dt)
fake_datetime_module.date = FakeDate
fake_datetime_module.datetime = FakeDatetime
fake_datetime_module.timedelta = real_dt.timedelta

orig = sys.modules.get('datetime')
sys.modules['datetime'] = fake_datetime_module

try:
    if 'humanize.time' in sys.modules:
        del sys.modules['humanize.time']

    import humanize.time

    # Test 1: tz-aware datetime
    tz = real_dt.timezone(real_dt.timedelta(hours=11))
    value = real_dt.datetime(2023, 10, 16, 1, 0, tzinfo=tz)
    result = humanize.time.naturalday(value)
    print(f"tz-aware test: {result}")

    # Test 2: naive datetime  
    naive_dt = real_dt.datetime(2023, 10, 16, 12, 0)
    result2 = humanize.time.naturalday(naive_dt)
    print(f"naive test: {result2}")

finally:
    sys.modules['datetime'] = orig
    for key in list(sys.modules.keys()):
        if 'humanize' in key:
            del sys.modules[key]
